function hashText(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) { h = ((h << 5) + h + s.charCodeAt(i)) | 0; }
  return 'h' + (h >>> 0).toString(16);
}
const LEVELS = ['Low', 'Medium', 'High', 'Critical'];
const rank = l => Math.max(0, LEVELS.indexOf(String(l || '')));
const RULES = [
  { cat: 'Allegation against a person or company', level: 'Critical', re: /\b(fraud|scam|scammer|cheat(ed|ing)?|corrupt(ion)?|money laundering|embezzl\w*|brib(e|ed|ery)|ponzi)\b|धोखाधड़ी|घोटाला|ठगी/i },
  { cat: 'Financial or investment claim', level: 'High', re: /guarantee(d)?\s+(returns?|profits?|income)|risk[- ]free\s+(investment|returns?)|double your (money|investment)|\b\d+(\.\d+)?\s?%\s+(returns?|roi|profit)|stock tips?|buy (this|these) (stock|shares|coins?)|crypto (tips?|signals?)|गारंटी(ड)?\s?(रिटर्न|मुनाफा)/i },
  { cat: 'Medical or health claim', level: 'High', re: /\b(cures?|heals?|prevents?)\s+(cancer|diabetes|covid|depression|disease|anxiety)|clinically proven|miracle (cure|drug)/i },
  { cat: 'Legal or regulatory matter', level: 'High', re: /\b(lawsuit|sued|suing|court case|litigation|illegal|in violation of|sebi (order|action|penalty)|rbi (action|penalty)|non-compliant)\b|मुकदमा|अवैध/i },
  { cat: 'Political or religious topic', level: 'High', re: /\b(bjp|congress party|aam aadmi|election(s)?|prime minister|hindu|muslim|christian|sikh|religio(n|us)|caste|khalistan)\b|चुनाव|धर्म|जाति/i },
  { cat: 'Personal or confidential data', level: 'High', re: /[\w.+-]+@[\w-]+\.[a-z]{2,}|(\+91[\s-]?)?\b[6-9]\d{9}\b|\b(confidential|internal only|under nda|not (yet )?public)\b/i },
  { cat: 'Absolute or superlative claim', level: 'Medium', re: /\b(guaranteed|100% (sure|success|results)|best in (the )?(world|india|industry)|number one|never fails?|always works)\b/i },
  { cat: 'Client or testimonial claim', level: 'Medium', re: /\b(our client|a client of ours|customer told us|testimonial)\b/i },
];
const STAT = /\b\d+(\.\d+)?\s?(%|percent|x faster|crore|lakh|million|billion)/i;

return $input.all().map((item, i) => {
  const r = item.json;
  const text = String(r.Post_Text || '');
  const hash = hashText(text);
  if (!text.trim()) throw new Error('Risk Check received an empty post' + (r.Content_ID ? ' (' + r.Content_ID + ')' : ''));
  const force = r.force_risk_check === true || String(r.force_risk_check) === 'true';
  const needs = force
    || !String(r.Risk_Checked_At || '').trim()
    || String(r.Risk_Hash || '') !== hash
    || String(r.Risk_Review_Status || '') !== 'Completed';
  const flags = [];
  let ruleLevel = 'Low';
  for (const rule of RULES) {
    const m = text.match(rule.re);
    if (m) {
      flags.push(rule.cat + ' ("' + m[0].slice(0, 40) + '")');
      if (rank(rule.level) > rank(ruleLevel)) ruleLevel = rule.level;
    }
  }
  const stat = text.match(STAT);
  if (stat) {
    const sourced = String(r.Sources_Used || '').trim().length > 0;
    flags.push((sourced ? 'Statistic to verify against sources' : 'Statistic with no source attached') + ' ("' + stat[0] + '")');
    const lvl = sourced ? 'Medium' : 'High';
    if (rank(lvl) > rank(ruleLevel)) ruleLevel = lvl;
  }
  return {
    json: { ...r, _risk_hash: hash, _risk_needed: needs, _rule_level: ruleLevel, _rule_flags: flags, _first_check: !String(r.Risk_Checked_At || '').trim() },
    pairedItem: { item: i },
  };
});

