parameters.jsCode:
const LEVELS = ['Low', 'Medium', 'High', 'Critical'];
const rank = l => LEVELS.indexOf(String(l || ''));
const NL = String.fromCharCode(10);
const zone = 'Asia/Kolkata';
const PRIMARY_MODEL = 'anthropic/claude-sonnet-5.5';
const FALLBACK_MODEL = 'gpt-5.5';
const PRICING_VERSION = 'estimate-v1-primary-rates-3-15-per-mtok-unverified';
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = $('Needs Risk Review?').itemMatching(i).json;
  const res = items[i].json || {};
  const v = res.output && typeof res.output === 'object' ? res.output : null;
  const reviewOk = !!(v && rank(v.risk_level) >= 0);

  const candidates = [{ level: r._rule_level, by: 'keyword scan' }];
  if (reviewOk) candidates.push({ level: v.risk_level, by: 'independent AI review' });
  else candidates.push({ level: 'High', by: 'automatic fail-safe (AI review unavailable)' });
  if (r._first_check && rank(r.Risk_Level) >= 0) candidates.push({ level: r.Risk_Level, by: 'writer self-assessment' });
  if (rank(r.Human_Risk_Level) >= 0) candidates.push({ level: r.Human_Risk_Level, by: 'human risk assessment' });
  if (rank(r.Trusted_Risk_Level) >= 0) candidates.push({ level: r.Trusted_Risk_Level, by: 'trusted prior classification' });
  let final = candidates[0];
  for (const c of candidates) if (rank(c.level) > rank(final.level)) final = c;

  const issues = reviewOk && Array.isArray(v.issues) ? v.issues : [];
  const reviewError = reviewOk ? '' : (res.error ? String(res.error.message || res.error).slice(0, 200) : 'Reviewer returned no valid verdict');
  const reviewStatus = reviewOk ? 'Completed' : 'Needs Human Verification';
  const eligible = reviewOk ? 'Yes' : 'No';
  const needsAdmin = rank(final.level) >= 2 || !reviewOk;

  const notes = [];
  notes.push(final.level + ' (set by ' + final.by + ')');
  if (reviewOk) {
    notes.push('Review: ' + String(v.summary || '').slice(0, 300));
    issues.slice(0, 4).forEach(x => notes.push('- "' + String(x.excerpt || '').slice(0, 80) + '": ' + x.concern + ' Fix: ' + x.suggested_fix));
  } else {
    notes.push('Independent AI review did not complete (' + reviewError + '). Blocked from normal approval until an Admin verifies it.');
  }
  if (r._rule_flags.length) notes.push('Keyword scan: ' + r._rule_flags.join('; '));
  notes.push('AI risk screening is not legal or regulatory clearance.');

  const previous = String(r.Risk_Level || '');
  const categories = (reviewOk ? (v.categories || []) : ['Review unavailable'])
    .concat(r._rule_flags.map(f => f.split(' (')[0]))
    .filter((x, k, a) => x && a.indexOf(x) === k);
  const sourcesText = String(r.Sources_Used || r.All_Sources || '').trim();
  const sourceState = String(r.Source_Verification || '').trim() || (sourcesText ? 'sources_attached_not_verified' : 'no_sources_attached');
  const executionId = String(r.Execution_ID || r.execution_id || $execution.id);
  const checkedAt = DateTime.now().setZone(zone).toISO();

  const row = {};
  for (const k of Object.keys(r)) if (!k.startsWith('_') && k !== 'force_risk_check' && k !== 'risk_check_needed') row[k] = r[k];
  Object.assign(row, {
    Risk_Level: final.level,
    Risk_Notes: notes.join(NL).slice(0, 1500),
    Admin_Approval_Required: needsAdmin ? 'Yes' : 'No',
    Risk_Flags: categories.join(', '),
    Risk_Hash: r._risk_hash,
    Risk_Checked_At: checkedAt,
    Risk_Review_Status: reviewStatus,
    Approval_Eligible: eligible
  });

  const estIn = Math.ceil((String(r.Post_Text || '').length + sourcesText.length + 2600) / 4);
  const estOut = reviewOk ? Math.ceil(JSON.stringify(v).length / 4) + 20 : 0;
  const estCost = reviewOk ? Math.round((estIn * 3 / 1000000 + estOut * 15 / 1000000) * 100000) / 100000 : 0;

  out.push({
    json: {
      row,
      risk_changed: previous !== final.level,
      previous_risk_level: previous,
      review_ok: reviewOk,
      execution_id: executionId,
      cost: {
        idempotency_key: [row.Post_ID, executionId, 'risk_review', row.Content_ID || ('item-' + i)].join(':'),
        provider: 'unattributed (openrouter primary or openai fallback)',
        model: 'unattributed (primary ' + PRIMARY_MODEL + ', fallback ' + FALLBACK_MODEL + ')',
        input_tokens: estIn,
        output_tokens: estOut,
        cost_usd: estCost,
        pricing_version: PRICING_VERSION,
        usage_type: 'estimated'
      },
      audit_details: {
        previous_risk_level: previous,
        new_risk_level: final.level,
        final_set_by: final.by,
        risk_categories: categories,
        flagged_excerpts: issues.map(x => String(x.excerpt || '')).filter(Boolean).slice(0, 10),
        suggested_fixes: issues.map(x => ({ excerpt: String(x.excerpt || '').slice(0, 120), concern: x.concern, fix: x.suggested_fix })).slice(0, 10),
        keyword_flags: r._rule_flags,
        review_status: reviewStatus,
        review_error: reviewError,
        approval_eligible: eligible,
        admin_approval_required: needsAdmin,
        content_hash: r._risk_hash,
        source_verification_state: sourceState,
        execution_id: executionId,
        checked_at: checkedAt
      }
    },
    pairedItem: { item: i }
  });
}
return out;

return $input.all().map((it, i) => {
  const row = {};
  for (const k of Object.keys(it.json)) if (!k.startsWith('_') && k !== 'force_risk_check' && k !== 'risk_check_needed') row[k] = it.json[k];
  row.Risk_Changed = 'No';
  return { json: row, pairedItem: { item: i } };
});
